lines=['# Eight-suite diagnostic closeout','','Candidate `7f7e487c47a87e871dfef53345e2b71288008bff` remains **not release-approved**. All eight official suites passed independent audits; all required diagnostics are retained. Labs was not changed or published.','','## Worst same-node regressions','','There are17 numerical increases, not20; none are invented. Same-node correctness and measurement direction are established, but confidence differs. Call, website, shell-string and tiny-full-build specimens have particularly strong nonoverlap evidence. Smaller increases remain descriptive.','','| Rank | Benchmark / scenario | Old ms | Candidate ms | Increase | Evidence confidence |','|---:|---|---:|---:|---:|---|']
for i,x in enumerate(a['regressions'][:20],1):lines.append(f"| {i} | {x['benchmark']} / {x['scenario']} | {x['old_ms']:.3f} | {x['candidate_ms']:.3f} | {x['change_pct']:.2f}% | {x['confidence']} |")
lines+=['','## Best same-node improvements — top20','','Small paired controls are descriptive, not population significance tests. Task historical gains are excluded from this ranking.','','| Rank | Benchmark / scenario | Old ms | Candidate ms | Improvement |','|---:|---|---:|---:|---:|']
